(function(){
 const fields=['t','t0','selected','fleet','dispatchJobs','rcTasks','rcQualifications','crewTasks','mdtMessages','mdtDrafts','logs','placements','waiting','activeCall','nextId','standbyDone','rcKind','rcChosen','rcEquipmentIds','rcEquipmentQuantities','rcEquipmentOwners','rcMethod','rcLocation','detail','rcTab','screen','callAnswers','callType2','callOverride','otherServices','callDialogue'];
 class VectorSession{
  constructor(app,incidents){this.app=app;this.incidents=incidents;this.revision=0;this.ready=false;this.busy=false;this.blocked=false;this.last='';this.timer=null;this.stopped=false;this.leave=e=>{if(this.ready&&(this.busy||this.key()!==this.last)){e.preventDefault();e.returnValue='';}};window.addEventListener('beforeunload',this.leave);}
  snapshot(){const state={};for(const k of fields)if(this.app.state[k]!==undefined)state[k]=this.app.state[k];return {schema:1,state,incidents:this.incidents};}
  key(){const d=this.snapshot();delete d.state.t;return JSON.stringify(d);}
  async load(){if(this.busy)return;this.blocked=true;this.app.setState({sessionStatus:'Loading saved session',sessionBlocked:true,sessionRetry:false});try{const r=await fetch('/api/session',{cache:'no-store'});if(!r.ok)throw Error();const b=await r.json();if(b.data){if(b.data.schema!==1||!b.data.state||!Array.isArray(b.data.incidents))throw Error();this.incidents.splice(0,this.incidents.length,...b.data.incidents);this.app.setState(b.data.state);}this.revision=b.revision;this.last=this.key();this.ready=true;this.blocked=false;this.app.setState({sessionStatus:b.data?'Saved session restored':'Ready · new session',sessionBlocked:false,sessionRetry:false,sessionConflict:false});}catch{this.app.setState({sessionStatus:'Saved session unavailable. Retry to continue.',sessionBlocked:true,sessionRetry:true});}}
  changed(){if(!this.ready||this.blocked||this.stopped||this.key()===this.last)return;clearTimeout(this.timer);this.timer=setTimeout(()=>this.save(),250);}
  async save(){if(!this.ready||this.busy||this.stopped)return;const key=this.key();if(key===this.last)return;this.busy=true;this.app.setState({sessionStatus:'Saving changes…',sessionRetry:false});try{const r=await fetch('/api/session',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision:this.revision,data:this.snapshot()})});if(r.status===409){this.blocked=true;this.app.setState({sessionStatus:'A newer session was saved elsewhere. Reload it to continue.',sessionBlocked:true,sessionConflict:true,sessionRetry:false});return;}if(!r.ok)throw Error();const b=await r.json();this.revision=b.revision;this.last=key;this.blocked=false;this.app.setState({sessionStatus:'Saved · '+new Date(b.savedAt).toLocaleTimeString(),sessionBlocked:false,sessionRetry:false});}catch{this.blocked=true;this.app.setState({sessionStatus:'Changes not saved. Keep this page open and retry.',sessionBlocked:true,sessionRetry:true});}finally{this.busy=false;if(!this.blocked)this.changed();}}
  retry(){return this.ready?this.save():this.load();}
  dispose(){this.stopped=true;clearTimeout(this.timer);window.removeEventListener('beforeunload',this.leave);}
 }
 window.VectorSession=VectorSession;
})();
